    try: src=open(f,errors='ignore').read().splitlines()
    except: continue
    timers=set()
    for i,l in enumerate(src):
        for m in re.finditer(r'(?:timer_setup|setup_timer|DEFINE_TIMER)\s*\(\s*[^,]+,\s*(\w+)',l):
            timers.add(m.group(1))
        for m in re.finditer(r'(\w+)\s*=\s*\w*FUNCTION',l): pass
    # also hrtimer .function = and INIT_DELAYED_WORK
    for i,l in enumerate(src):
