        for m in re.finditer(r'INIT_DELAYED_WORK\s*\(\s*[^,]+,\s*(\w+)',l): timers.add(m.group(1))
        for m in re.finditer(r'INIT_DEFERRABLE_WORK\s*\(\s*[^,]+,\s*(\w+)',l): timers.add(m.group(1))
    if not timers: continue
    cur=None
    for i,l in enumerate(src,1):
        m=re.match(r'\s*(?:static\s+)?(?:void|int)\s+(\w+)\s*\(',l)
